 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
            c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
            boxes.append((c0, [[grid[y][x] for x in range(c0, c1 + 1)] for y in range(r0, r1 + 1)]))
    boxes.sort(key=lambda item: item[0])
    out = [[] for _ in range(max(len(box[1]) for box in boxes))]
    for _, patch in boxes:
        for y in range(len(out)):
            out[y].extend(patch[y] if y < len(patch) else [0] * len(patch[0]))
    return out
